    CONSTRAINT appraisal_cycles_status_check CHECK (((status)::text = ANY (ARRAY[('Draft'::character varying)::text, ('Active'::character varying)::text, ('Completed'::character varying)::text, ('Cancelled'::character varying)::text])))
);


